+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("month and weekday names", () => {
+  expect(nextRun("0 9 * * mon-fri", at("2026-01-02T10:00:00Z")).toISOString()).toBe("2026-01-05T09:00:00.000Z");
+  expect(nextRun("0 0 1 JAN *", at("2026-02-01T00:00:00Z")).toISOString()).toBe("2027-01-01T00:00:00.000Z");
+});
+
+test("Sunday as 7", () => {
+  expect(nextRun("0 0 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+  expect(nextRun("0 0 * * 0-7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-02T00:00:00.000Z");
+});
+
+test("a bare start with a step runs to the end of the field", () => {
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:25:00Z")).toISOString()).toBe("2026-01-01T00:45:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:05:00.000Z");
+});
+
+test("a range with a step", () => {
+  expect(nextRun("0-59/15 * * * *", at("2026-01-01T10:50:00Z")).toISOString()).toBe("2026-01-01T11:00:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:20:00Z")).toISOString()).toBe("2026-01-01T00:30:00.000Z");
+});
+
+test("day of month or day of week when both are restricted", () => {
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-12T00:00:00Z")).toISOString()).toBe("2026-01-15T00:00:00.000Z");
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+});
+
+test("a full day of month leaves the day to day of week", () => {
+  expect(nextRun("0 0 1-31 * 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+});
+
+test("29 February", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+});
+
+test("invalid expressions throw", () => {
+  for (const expr of ["*/0 * * * *", "5/ * * * *", "10-5 * * * *", "60 * * * *", "0 0 * FOO *", "0 0 0 * *", "0 0 * JAN- *", "1-2-3 * * * *", "0 0 30 2 *"]) {
+    expect(() => nextRun(expr, at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+  }
+});
