+  expect(nextRun("0 0 1,15 * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-13T00:00:00Z")).toISOString()).toBe("2026-01-15T00:00:00.000Z");
+});
+
+test("a day field that allows every value leaves the other field in charge", () => {
+  expect(nextRun("0 0 15 * 0-6", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-15T00:00:00.000Z");
+  expect(nextRun("0 0 1-31 * 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
