diff -ruN '--exclude=node_modules' '--exclude=.git' a/cron.rules.test.ts b/cron.rules.test.ts
--- a/cron.rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/cron.rules.test.ts	2026-10-28 07:40:22.154867812 +0000
@@ -0,0 +1,61 @@
+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("names for months and weekdays", () => {
+  expect(nextRun("0 0 1 JAN *", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2027-01-01T00:00:00.000Z");
+  expect(nextRun("0 0 * * mon-fri", at("2026-01-02T09:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+});
+
+test("a step after a single value runs to the end of the field", () => {
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:05:00Z")).toISOString()).toBe("2026-01-01T00:25:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:45:00Z")).toISOString()).toBe("2026-01-01T01:05:00.000Z");
+});
+
+test("steps over ranges and stars", () => {
+  expect(nextRun("0-59/15 * * * *", at("2026-01-01T00:15:00Z")).toISOString()).toBe("2026-01-01T00:30:00.000Z");
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:45:00Z")).toISOString()).toBe("2026-01-01T01:00:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:20:00Z")).toISOString()).toBe("2026-01-01T00:30:00.000Z");
+});
+
+test("Sunday as 7 is the same as Sunday as 0", () => {
+  expect(nextRun("0 0 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+  expect(nextRun("0 0 * * 5-7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-02T00:00:00.000Z");
+  expect(nextRun("0 0 * * SUN", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+});
+
+test("day of month and day of week are OR-ed when both are restricted", () => {
+  // 1st, 15th, and every Monday; 2026-01-05 is a Monday.
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-05T00:00:00Z")).toISOString()).toBe("2026-01-12T00:00:00.000Z");
+});
+
+test("a day field that allows every value leaves the day to the other field", () => {
+  // Every day of month, but only Mondays.
+  expect(nextRun("0 0 * * 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  // Every weekday written as 0-6, only the 13th.
+  expect(nextRun("0 0 13 * 0-6", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-13T00:00:00.000Z");
+});
+
+test("the 29th of February", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+  expect(nextRun("0 0 29 2 *", at("2096-03-01T00:00:00Z")).toISOString()).toBe("2104-02-29T00:00:00.000Z");
+});
+
+test("invalid expressions throw", () => {
+  for (const expr of [
+    "*/0 * * * *",
+    "5/0 * * * *",
+    "x * * * *",
+    "1.5 * * * *",
+    "5-1 * * * *",
+    "60 * * * *",
+    "* * * FOO *",
+    "* * * * MON-",
+    "1,,2 * * * *",
+    "0 0 30 2 *",
+  ]) {
+    expect(() => nextRun(expr, at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+  }
+});
