+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("month and day names, any case", () => {
+  expect(nextRun("0 9 * jan mon", at("2026-01-01T10:00:00Z")).toISOString()).toBe("2026-01-05T09:00:00.000Z");
+  expect(nextRun("0 0 * JAN-FEB *", at("2026-06-01T00:00:00Z")).toISOString()).toBe("2027-01-01T00:00:00.000Z");
+});
+
+test("Sunday is 0 or 7", () => {
+  expect(nextRun("0 8 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T08:00:00.000Z");
+  expect(nextRun("0 8 * * 0", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T08:00:00.000Z");
+});
+
+test("a bare start with a step runs to the end of the field", () => {
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:10:00Z")).toISOString()).toBe("2026-01-01T00:25:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:45:00Z")).toISOString()).toBe("2026-01-01T01:05:00.000Z");
+});
+
+test("ranges with steps", () => {
+  expect(nextRun("0-59/15 * * * *", at("2026-01-01T00:20:00Z")).toISOString()).toBe("2026-01-01T00:30:00.000Z");
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:50:00Z")).toISOString()).toBe("2026-01-01T01:00:00.000Z");
+});
+
+test("day of month or day of week when both are restricted", () => {
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 15 * 0-6", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-15T00:00:00.000Z");
+});
+
+test("day of month and day of week when one is unrestricted", () => {
+  expect(nextRun("0 0 * * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 1-31 * 3", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-07T00:00:00.000Z");
+});
+
+test("29 February", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+});
+
+test("invalid expressions throw", () => {
+  for (const expr of [
+    "60 * * * *",
+    "5-3 * * * *",
+    "*/0 * * * *",
+    "*/x * * * *",
+    "5/ * * * *",
+    "0 0 * * 8",
+    "0 0 * FOO *",
+    "0 0 * * MON-",
+    "0 0 0 * *",
+    "0 0 31 2 *",
