+import { expect, test } from "bun:test";
+import { satisfies } from "./semver";
+
+test("0.x carets stop at the left-most non-zero part", () => {
+  expect(satisfies("0.2.9", "^0.2.3")).toBe(true);
+  expect(satisfies("0.3.0", "^0.2.3")).toBe(false);
+  expect(satisfies("0.0.3", "^0.0.3")).toBe(true);
+  expect(satisfies("0.0.4", "^0.0.3")).toBe(false);
+  expect(satisfies("0.9.0", "^0.x")).toBe(true);
+  expect(satisfies("1.0.0", "^0.x")).toBe(false);
+  expect(satisfies("0.0.9", "^0.0.x")).toBe(true);
+  expect(satisfies("0.1.0", "^0.0")).toBe(false);
+});
+
+test("partial versions and x-ranges", () => {
+  expect(satisfies("1.9.9", "1.x")).toBe(true);
+  expect(satisfies("2.0.0", "1.x")).toBe(false);
+  expect(satisfies("1.2.9", "1.2")).toBe(true);
+  expect(satisfies("1.3.0", "1.2")).toBe(false);
+  expect(satisfies("1.2.9", "1.2.x")).toBe(true);
+  expect(satisfies("1.2.0", "1")).toBe(true);
+  expect(satisfies("3.0.0", "*")).toBe(true);
+});
+
+test("partial versions with operators", () => {
+  expect(satisfies("2.0.0", ">1")).toBe(true);
+  expect(satisfies("1.9.9", ">1")).toBe(false);
+  expect(satisfies("1.3.0", ">1.2")).toBe(true);
+  expect(satisfies("1.2.9", ">1.2")).toBe(false);
+  expect(satisfies("1.2.0", ">=1.2")).toBe(true);
+  expect(satisfies("1.2.0-beta", "<1.2")).toBe(false);
+  expect(satisfies("1.1.9", "<1.2")).toBe(true);
+  expect(satisfies("1.2.9", "<=1.2")).toBe(true);
+  expect(satisfies("1.3.0", "<=1.2")).toBe(false);
+  expect(satisfies("1.9.0", "=1.2")).toBe(false);
+  expect(satisfies("1.2.5", "=1.2")).toBe(true);
+  expect(satisfies("1.0.0", ">*")).toBe(false);
+  expect(satisfies("1.0.0", "<*")).toBe(false);
+});
+
+test("tilde with partial versions", () => {
+  expect(satisfies("1.9.0", "~1")).toBe(true);
+  expect(satisfies("2.0.0", "~1")).toBe(false);
+  expect(satisfies("1.2.9", "~1.2")).toBe(true);
+  expect(satisfies("1.3.0", "~1.2")).toBe(false);
+  expect(satisfies("1.2.3-beta.3", "~1.2.3-beta.2")).toBe(true);
+  expect(satisfies("1.2.4-beta.3", "~1.2.3-beta.2")).toBe(false);
+  expect(satisfies("1.2.3-alpha", "~1.2.3-beta.2")).toBe(false);
+});
+
+test("hyphen ranges", () => {
+  expect(satisfies("1.2.0", "1.2 - 2.3.4")).toBe(true);
+  expect(satisfies("2.3.4", "1.2 - 2.3.4")).toBe(true);
+  expect(satisfies("2.3.5", "1.2 - 2.3.4")).toBe(false);
+  expect(satisfies("2.3.9", "1.2.3 - 2.3")).toBe(true);
+  expect(satisfies("2.4.0", "1.2.3 - 2.3")).toBe(false);
+  expect(satisfies("2.9.9", "1.2.3 - 2")).toBe(true);
+  expect(satisfies("3.0.0", "1.2.3 - 2")).toBe(false);
+  expect(satisfies("1.2.2", "1.2.3 - 2")).toBe(false);
+});
+
+test("prerelease versions need a comparator on the same MAJOR.MINOR.PATCH", () => {
+  expect(satisfies("1.2.3-beta.4", ">=1.2.3-alpha")).toBe(true);
+  expect(satisfies("3.4.5-beta", ">=1.2.3-alpha")).toBe(false);
+  expect(satisfies("1.2.3-beta", "*")).toBe(false);
+  expect(satisfies("1.9.0-beta", "^1.2.3")).toBe(false);
+  expect(satisfies("1.2.3-beta.2", "^1.2.3-beta.2")).toBe(true);
+  expect(satisfies("2.0.0-0", "<2.0.0-0")).toBe(false);
+});
+
+test("prerelease ordering compares identifier by identifier", () => {
+  expect(satisfies("1.0.0-alpha.10", ">1.0.0-alpha.9")).toBe(true);
+  expect(satisfies("1.0.0-alpha.1", ">1.0.0-alpha")).toBe(true);
+  expect(satisfies("1.0.0-1", "<1.0.0-alpha")).toBe(true);
+  expect(satisfies("1.0.0", ">1.0.0-rc.1")).toBe(true);
+});
+
+test("invalid versions and ranges", () => {
+  expect(satisfies("01.2.3", "*")).toBe(false);
+  expect(satisfies("1.2.3-01", "*")).toBe(false);
+  expect(satisfies("1.2.3", "1.x.3")).toBe(false);
+  expect(satisfies("1.2.3", "1.2.3 - ")).toBe(false);
+});
